// Lógica completa de atendimento WhatsApp
const message = $input.all()[0].json;

// VALIDAÇÃO CRÍTICA: Verificar se a requisição contém dados válidos de WhatsApp
if (!message || !message.key || !message.key.remoteJid) {
  return [];
}

const remoteJid = message.key.remoteJid;

// Validar se remoteJid não está vazio e é um número válido
if (!remoteJid || typeof remoteJid !== 'string' || remoteJid.trim() === '') {
  return [];
}

// Filtro: ignorar mensagens próprias e grupos
if (message.key.fromMe === true || remoteJid.includes('@g.us')) {
  return [];
}

const messageText = message.message && message.message.conversation ? message.message.conversation : '';
const textLower = messageText.toLowerCase().trim();

// Configurações
const evolutionApiUrl = 'https://api.pracinha.online';
const instanceName = 'Variant';
const apiKey = '429683C4C977415CAAFCCE10F7D57E11';
const cardapioLink = 'cardapio-cidadela.vercel.app';

// Detectar rota e preparar resposta
let responseText = '';

if (textLower === '1' || textLower === '1️⃣') {
  responseText = `Acesse nosso cardápio no link abaixo para escolher seus itens e fazer o pedido: ${cardapioLink}`;
} else if (textLower === '2' || textLower === '2️⃣') {
  responseText = 'Perfeito! Lembramos que a nossa taxa de visita técnica é de R$ 100,00 (mais o valor do serviço a ser executado).\n\nPor favor, informe seu nome completo:';
} else if (textLower === '3' || textLower === '3️⃣') {
  responseText = `🎮 Acesse a Arena de Batalha da Cidadela: ${cardapioLink}/cidadela/battle\n\nJogue online contra outros pracinhas!`;
} else {
  responseText = 'Olá! Seja bem-vindo(a). Por favor, responda digitando o número da opção desejada:\n\n1️⃣ - Cardápio / Fazer Pedido\n2️⃣ - Assistência Técnica\n3️⃣ - Arena de Batalha (Jogos Online)';
}

return [{
  json: {
    evolutionApiUrl,
    instanceName,
    apiKey,
    number: remoteJid,
    text: responseText
  }
}];

// Processar pedido do cardápio com proteções de segurança
const payload = $input.all()[0].json;

// ============================================
// PROTEÇÃO CONTRA SPAM E DISPARO EM MASSA
// ============================================

// Validar campos obrigatórios
const required = ['cliente', 'telefone', 'endereco', 'total', 'itens', 'tipo_entrega', 'origem', 'comanda', 'evento', 'timestamp', 'pagamento'];
const missing = required.filter(f => !payload[f]);

if (missing.length > 0 || payload.origem !== 'CIDADELA_PWA') {
  return [{
    json: {
      success: false,
      error: 'validation_error',
      message: 'Dados inválidos'
    }
  }];
}

// Sanitizar telefone (apenas números, máximo 15 dígitos)
const telefoneSanitized = payload.telefone.replace(/[^0-9]/g, '');
if (telefoneSanitized.length < 10 || telefoneSanitized.length > 15) {
  return [{
    json: {
      success: false,
      error: 'invalid_phone',
      message: 'Telefone inválido'
    }
  }];
}

// Validar total (não pode ser negativo ou absurdo)
if (payload.total < 0 || payload.total > 100000) {
  return [{
    json: {
      success: false,
      error: 'invalid_total',
      message: 'Valor total inválido'
    }
  }];
}

// Validar itens (deve ter pelo menos 1 item, máximo 50)
if (!Array.isArray(payload.itens) || payload.itens.length === 0 || payload.itens.length > 50) {
  return [{
    json: {
      success: false,
      error: 'invalid_items',
      message: 'Lista de itens inválida'
    }
  }];
}

// Validar cada item
for (const item of payload.itens) {
  if (!item.name || !item.quantity || !item.total) {
    return [{
      json: {
        success: false,
        error: 'invalid_item',
        message: 'Item inválido'
      }
    }];
  }
  if (item.quantity < 1 || item.quantity > 100) {
    return [{
      json: {
        success: false,
        error: 'invalid_quantity',
        message: 'Quantidade inválida'
      }
    }];
  }
  if (item.total < 0 || item.total > 10000) {
    return [{
      json: {
        success: false,
        error: 'invalid_item_total',
        message: 'Valor do item inválido'
      }
    }];
  }
}

// Validar timestamp (não pode ser muito antigo ou futuro)
const timestamp = new Date(payload.timestamp);
const now = new Date();
const diffMinutes = (now - timestamp) / 60000;
if (Math.abs(diffMinutes) > 60) {
  return [{
    json: {
      success: false,
      error: 'invalid_timestamp',
      message: 'Timestamp inválido'
    }
  }];
}

// Sanitizar nome do cliente (máximo 100 caracteres, remover caracteres perigosos)
const clienteSanitized = payload.cliente.replace(/[<>"'&]/g, '').substring(0, 100);
if (clienteSanitized.length < 2) {
  return [{
    json: {
      success: false,
      error: 'invalid_client_name',
      message: 'Nome do cliente inválido'
    }
  }];
}

// Validar método de pagamento
const validPayments = ['pix', 'dinheiro', 'cartao'];
if (!validPayments.includes(payload.pagamento)) {
  return [{
    json: {
      success: false,
      error: 'invalid_payment',
      message: 'Método de pagamento inválido'
    }
  }];
}

// Configurações Evolution API
const evolutionApiUrl = 'https://api.pracinha.online';
const instanceName = 'Variant';
const apiKey = '429683C4C977415CAAFCCE10F7D57E11';
const restauranteNumber = payload.restaurante_whatsapp || '5548999880030';

// Formatar mensagem comanda
let pagamentoText = payload.pagamento;
if (payload.pagamento === 'dinheiro') pagamentoText = `Dinheiro (Troco p/ R$ ${payload.troco || '0'})`;
else if (payload.pagamento === 'cartao') pagamentoText = 'Cartão';

const itensText = payload.itens.map(i => `- ${i.quantity}x ${i.name} (R$ ${i.total.toFixed(2)})${i.observacoes ? `\n  _Obs: ${i.observacoes.substring(0, 200)}_` : ''}`).join('\n');
const enderecoText = payload.tipo_entrega === 'entrega' ? payload.endereco.substring(0, 200) : 'Retirada no balcão';
const tipoText = payload.tipo_entrega === 'entrega' ? 'Delivery' : 'Retirada';

const mensagem = `==============================\n   *NOVO PEDIDO - CIDADELA*\n==============================\n*Cliente:* ${clienteSanitized}\n*Telefone:* ${telefoneSanitized}\n*Tipo:* ${tipoText}\n*Endereço:* ${enderecoText}\n\n------------------------------\n*ITENS DO PEDIDO:*\n${itensText}\n------------------------------\n\n*FORMA DE PAGAMENTO:* ${pagamentoText}\n*TAXA DE ENTREGA:* R$ ${payload.taxa_entrega.toFixed(2)}\n*TOTAL DO PEDIDO:* R$ ${payload.total.toFixed(2)}\n==============================`;

return [{
  json: {
    success: true,
    comanda: payload.comanda,
    mensagem_formatada: mensagem,
    evolutionApiUrl,
    instanceName,
    apiKey,
    restaurante_number: restauranteNumber,
    cliente_number: telefoneSanitized
  }
}];

// Validar código de autenticação com proteções
const payload = $input.all()[0].json;

// ============================================
// PROTEÇÃO CONTRA ATAQUES DE AUTENTICAÇÃO
// ============================================

// Validar campos obrigatórios
if (!payload.codigo || typeof payload.codigo !== 'string') {
  return [{
    json: {
      success: false,
      autenticado: false,
      erro: 'invalid_code'
    }
  }];
}

// Sanitizar código (máximo 50 caracteres, apenas alfanumérico e hífens)
const codigoSanitized = payload.codigo.replace(/[^a-zA-Z0-9-]/g, '').substring(0, 50);
if (codigoSanitized.length < 5) {
  return [{
    json: {
      success: false,
      autenticado: false,
      erro: 'invalid_code'
    }
  }];
}

// Validar origem
if (payload.origem !== 'CIDADELA_PWA') {
  return [{
    json: {
      success: false,
      autenticado: false,
      erro: 'invalid_origin'
    }
  }];
}

// Simular validação (em produção usar banco real)
const validCodes = {
  'ADMIN123': { nivel: 'admin' },
  'OPER456': { nivel: 'operador' }
};

const codeData = validCodes[codigoSanitized];
if (!codeData) {
  return [{
    json: {
      success: false,
      autenticado: false,
      erro: 'invalid_code'
    }
  }];
}

const token = Buffer.from(`${codigoSanitized}_${Date.now()}`).toString('base64');

return [{
  json: {
    success: true,
    autenticado: true,
    nivel_acesso: codeData.nivel,
    token_sessao: token,
    expiracao: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
  }
}];

// Processar eventos de sessão de jogo com proteções
const payload = $input.all()[0].json;

// ============================================
// PROTEÇÃO CONTRA ABUSO EM JOGOS
// ============================================

const supabaseUrl = 'https://seu-projeto.supabase.co';
const supabaseKey = 'sua-chave-anon-publica';
const evolutionApiUrl = 'https://api.pracinha.online';
const instanceName = 'Variant';
const apiKey = '429683C4C977415CAAFCCE10F7D57E11';

// Validar campos obrigatórios
if (!payload.acao || !payload.game_type) {
  return [{
    json: {
      success: false,
      error: 'missing_fields',
      message: 'Campos obrigatórios: acao, game_type'
    }
  }];
}

// Validar ação (apenas ações permitidas)
const validActions = ['criar', 'entrar', 'atualizar', 'completar'];
if (!validActions.includes(payload.acao)) {
  return [{
    json: {
      success: false,
      error: 'invalid_action',
      message: 'Ação inválida'
    }
  }];
}

// Validar tipo de jogo
const validGameTypes = ['battle', 'trilha', 'iq_test'];
if (!validGameTypes.includes(payload.game_type)) {
  return [{
    json: {
      success: false,
      error: 'invalid_game_type',
      message: 'Tipo de jogo inválido'
    }
  }];
}

// Sanitizar nomes (máximo 50 caracteres)
const sanitizeName = (name) => (name || '').replace(/[<>"'&]/g, '').substring(0, 50);

const acao = payload.acao;
const gameType = payload.game_type;

let result = { success: false };
let whatsappNotification = null;

if (acao === 'criar') {
  // Validar player1
  if (!payload.player1_id || !payload.player1_name) {
    return [{
      json: {
        success: false,
        error: 'missing_player1'
      }
    }];
  }

  const sessionData = {
    game_type: gameType,
    player1_id: payload.player1_id.substring(0, 100),
    player1_name: sanitizeName(payload.player1_name),
    player1_data: payload.player1_data || {},
    status: 'waiting',
    current_turn: 1,
    game_state: payload.game_state || {}
  };

  result = {
    success: true,
    acao: 'criar',
    session_id: 'temp_' + Date.now(),
    message: 'Sessão criada com sucesso'
  };

} else if (acao === 'entrar') {
  // Validar session_id
  if (!payload.session_id) {
    return [{
      json: {
        success: false,
        error: 'missing_session_id'
      }
    }];
  }

  // Validar player2
  if (!payload.player2_id || !payload.player2_name) {
    return [{
      json: {
        success: false,
        error: 'missing_player2'
      }
    }];
  }

  result = {
    success: true,
    acao: 'entrar',
    session_id: payload.session_id,
    message: 'Entrou na sessão com sucesso'
  };

  // Notificar player1 via WhatsApp se tiver número e for válido
  if (payload.player1_phone) {
    const phoneSanitized = payload.player1_phone.replace(/[^0-9]/g, '');
    if (phoneSanitized.length >= 10 && phoneSanitized.length <= 15) {
      whatsappNotification = {
        number: phoneSanitized,
        text: `⚔️ Oponente encontrado!\n\nJogador: ${sanitizeName(payload.player2_name || 'Player 2')}\nJogo: ${gameType}\n\nBoa sorte!`
      };
    }
  }
}

return [{
  json: {
    ...result,
    evolutionApiUrl,
    instanceName,
    apiKey,
    whatsappNotification
  }
}];

// Enviar notificação WhatsApp se houver
const data = $input.all()[0].json;

if (!data.whatsappNotification) {
  return [];
}

return [{
  json: {
    evolutionApiUrl: data.evolutionApiUrl,
    instanceName: data.instanceName,
    apiKey: data.apiKey,
    number: data.whatsappNotification.number,
    text: data.whatsappNotification.text
  }
}];

// Processar movimentos/jogadas de jogo com proteções
const payload = $input.all()[0].json;

// ============================================
// PROTEÇÃO CONTRA ABUSO EM MOVIMENTOS
// ============================================

const supabaseUrl = 'https://seu-projeto.supabase.co';
const supabaseKey = 'sua-chave-anon-publica';

// Validar campos obrigatórios
if (!payload.session_id || !payload.player_id || !payload.move_type) {
  return [{
    json: {
      success: false,
      error: 'missing_fields',
      message: 'Campos obrigatórios: session_id, player_id, move_type'
    }
  }];
}

// Sanitizar IDs (máximo 100 caracteres)
const sanitizeId = (id) => (id || '').replace(/[^a-zA-Z0-9_-]/g, '').substring(0, 100);

// Validar session_id
const sessionIdSanitized = sanitizeId(payload.session_id);
if (sessionIdSanitized.length < 5) {
  return [{
    json: {
      success: false,
      error: 'invalid_session_id'
    }
  }];
}

// Validar player_id
const playerIdSanitized = sanitizeId(payload.player_id);
if (playerIdSanitized.length < 5) {
  return [{
    json: {
      success: false,
      error: 'invalid_player_id'
    }
  }];
}

// Validar player_number (apenas 1 ou 2)
if (payload.player_number && payload.player_number !== 1 && payload.player_number !== 2) {
  return [{
    json: {
      success: false,
      error: 'invalid_player_number'
    }
  }];
}

// Validar move_type (máximo 50 caracteres)
const moveTypeSanitized = (payload.move_type || '').replace(/[<>"'&]/g, '').substring(0, 50);
if (moveTypeSanitized.length < 1) {
  return [{
    json: {
      success: false,
      error: 'invalid_move_type'
    }
  }];
}

// Validar round_number (entre 1 e 1000)
const roundNumber = parseInt(payload.round_number) || 1;
if (roundNumber < 1 || roundNumber > 1000) {
  return [{
    json: {
      success: false,
      error: 'invalid_round_number'
    }
  }];
}

const moveData = {
  session_id: sessionIdSanitized,
  player_id: playerIdSanitized,
  player_number: payload.player_number || 1,
  move_type: moveTypeSanitized,
  move_data: payload.move_data || {},
  round_number: roundNumber
};

// Em produção: fazer POST para Supabase REST API
// POST /rest/v1/game_moves

return [{
  json: {
    success: true,
    move_id: 'move_' + Date.now(),
    message: 'Movimento registrado com sucesso',
    move: moveData
  }
}];

// Processar criação de trial administrativo com proteções
const payload = $input.all()[0].json;

// ============================================
// PROTEÇÃO CONTRA ABUSO DE TRIAL
// ============================================

const evolutionApiUrl = 'https://api.pracinha.online';
const instanceName = 'Variant';
const apiKey = '429683C4C977415CAAFCCE10F7D57E11';

// Validar campos obrigatórios
if (!payload.acao || payload.acao !== 'criar_trial' || !payload.store_name || !payload.admin_phone) {
  return [{
    json: {
      success: false,
      error: 'missing_fields',
      message: 'Campos obrigatórios: acao, store_name, admin_phone'
    }
  }];
}

// Sanitizar nome da loja (máximo 100 caracteres, remover caracteres perigosos)
const storeNameSanitized = payload.store_name.replace(/[<>"'&]/g, '').substring(0, 100);
if (storeNameSanitized.length < 2) {
  return [{
    json: {
      success: false,
      error: 'invalid_store_name',
      message: 'Nome da loja inválido'
    }
  }];
}

// Sanitizar telefone (apenas números, máximo 15 dígitos)
const phoneSanitized = payload.admin_phone.replace(/[^0-9]/g, '');
if (phoneSanitized.length < 10 || phoneSanitized.length > 15) {
  return [{
    json: {
      success: false,
      error: 'invalid_phone',
      message: 'Telefone inválido'
    }
  }];
}

// Gerar código de acesso
const accessCode = `FEB-${Math.random().toString(36).toUpperCase().slice(2, 8)}-TRIAL`;

// Calcular data de expiração (2 dias)
const trialStartedAt = new Date();
const trialExpiresAt = new Date(trialStartedAt);
trialExpiresAt.setDate(trialExpiresAt.getDate() + 2);

// Em produção: salvar no Supabase
// POST /rest/v1/admin_trials

return [{
  json: {
    success: true,
    access_code: accessCode,
    trial_expires_at: trialExpiresAt.toISOString(),
    message: 'Trial criado com sucesso',
    store_name: storeNameSanitized,
    admin_phone: phoneSanitized,
    evolutionApiUrl,
    instanceName,
    apiKey
  }
}];

// Enviar WhatsApp com código de acesso
const data = $input.all()[0].json;

if (!data.success || !data.access_code) {
  return [];
}

const mensagem = `🎉 *TRIAL CRIADO COM SUCESSO!*\n\n📱 *Loja:* ${data.store_name}\n🔑 *Código de Acesso:* ${data.access_code}\n⏰ *Expira em:* 2 dias\n\nUse este código para acessar o painel administrativo.\n\nApós expirar, entre em contato para obter o código definitivo de 1 ano.`;

return [{
  json: {
    evolutionApiUrl: data.evolutionApiUrl,
    instanceName: data.instanceName,
    apiKey: data.apiKey,
    number: data.admin_phone,
    text: mensagem
  }
}];
